const headers=['Nr.','Domeniu','Prioritate','Denumire','Explicația — din perspectiva site-ului','Variabile de intrare — primite de cesiro.com','Variabile expediate — trimise de cesiro.com'];
const data=rows.map(r=>[r[0],r[1],r[2],r[3],r[4],r[5].replaceAll('; ',';\n'),r[6]?.replaceAll('; ',';\n')]);
const last=5+data.length;
s.getRange(`A5:G${last}`).values=[headers,...data];
const t=s.tables.add(`A5:G${last}`,true,'CatalogAPI');t.showFilterButton=true;
s.getRange(`A5:G${last}`).format.font={name:'Arial',size:11,color:'#243746'};
