s.getRange(`A5:G${last}`).format.verticalAlignment='top';
const widths=[6,23,11,35,65,66,66];
widths.forEach((width,i)=>s.getRange(`${String.fromCharCode(65+i)}1:${String.fromCharCode(65+i)}${last}`).format.columnWidth=width);
s.getRange('A5:G5').format={fill:'#243746',font:{name:'Arial',size:11,bold:true,color:'#FFFFFF'},rowHeight:36,horizontalAlignment:'center',verticalAlignment:'center',wrapText:true};
data.forEach((row,i)=>{
 const n=i+6; const lines=Math.max(...row.map((v,j)=>String(v).split('\n').reduce((a,line)=>a+Math.max(1,Math.ceil(line.length/(widths[j]-3))),0)));
 s.getRange(`A${n}:G${n}`).format.rowHeight=Math.max(72,lines*15+12);
 s.getRange(`A${n}:G${n}`).format.fill=i%2===0?'#F0F4F7':'#FFFFFF';
 s.getRange(`D${n}`).format.font.bold=true;
});
s.freezePanes.freezeRows(5);
const g=wb.worksheets.add('Ghid');g.showGridLines=false;g.tabColor='#8B9AA5';
g.getRange('A2').values=[['Cum se folosește tabelul']];
const notes=[
 ['Scop','Catalog de funcții propuse pentru comunicarea cesiro.com cu aplicația de administrare, ERP/WMS, contabilitate, procesatorul de plăți, curieri, marketplace-uri și servicii de comunicare. Nu este o specificație tehnică finală.'],
 ['Intrare','Date care ajung la cesiro.com. Când site-ul apelează un serviciu extern, aici apare răspunsul serviciului. Când site-ul este apelat, aici apar parametrii cererii primite.'],
 ['Expediate','Date care pleacă de la cesiro.com. Când site-ul apelează un serviciu extern, aici apare cererea trimisă. Când site-ul este apelat, aici apare răspunsul site-ului. Coloanele descriu un schimb complet, nu ordinea temporală.'],
 ['Priorități','P1 = funcție de bază în fluxul comercial vizat; P2 = extindere sau funcție dependentă de modelul comercial. Prioritatea este propusă. Funcțiile marketplace și serviciile externe sunt necesare numai pentru integrările activate.'],
 ['Implementare','Starea implementării pe cesiro.com nu a fost auditată. Etichetele implementat/neimplementat din exemplul utilizatorului descriu exemplul, nu sunt transferate asupra acestei propuneri.'],
 ['Limite de acoperire','Lista acoperă fluxurile uzuale și extinse ale unui magazin online. Nu există o listă universală finită a tuturor funcțiilor posibile. Operațiunile și limitele exacte se confirmă pentru fiecare furnizor și contract.'],
 ['Denumiri de variabile','Câmpurile sunt propuneri de contract intern, în română și snake_case; nu reprezintă numele exacte ale câmpurilor API eMAG, Trendyol, Altex, Okazii sau ale altui furnizor. Adaptoarele traduc contractul intern în schema fiecăruia.'],
 ['Liste și obiecte','[] înseamnă listă; {} înseamnă obiect cu mai multe câmpuri. „sau” indică alternative. „optional” și „dacă este cazul” indică date dependente de context. Obligativitatea și tipul fiecărui câmp se stabilesc în specificația de implementare.'],
 ['Identificatori','produs_id, comanda_id și client_id sunt identificatori CESIRO. ID-urile externe se păstrează separat, împreună cu sursa/canalul. SKU identifică articolul sau varianta; EAN este identificatorul comercial, dacă există.'],
 ['Câmpuri comune','Nu sunt repetate în fiecare rând: autorizare, request_id, versiune_api; pentru modificări: idempotency_key și versiune_asteptata unde este necesar; pentru notificări: event_id, occurred_at și semnatura. Răspunsurile includ status și, la eșec, cod_eroare, mesaj și campuri_invalide.'],
 ['Date și sume','Datele se transmit în ISO 8601 cu fus orar; pentru afișare se poate folosi Europe/Bucharest. Sumele au monedă explicită, precizie și regulă de rotunjire stabilite. Prețurile precizează dacă includ TVA; unitățile de greutate și dimensiuni sunt explicite.'],
 ['Stoc și seturi','Se stabilește un singur sistem autoritar pentru stoc. Disponibil = fizic minus rezervat și blocat, ajustat prin regula de alocare. Pentru seturi asamblate, stocul se calculează din componente. Returul revine în stoc vandabil numai după recepție și inspecție.'],
 ['Stări separate','Statusul comenzii, plății, expedierii, returului și documentului fiscal se urmăresc separat. Factura nu dovedește încasarea; AWB-ul nu dovedește livrarea; cererea de retur nu dovedește recepția; storno nu dovedește rambursarea.'],
 ['Sincronizare robustă','Se stabilesc paginare, filtre de modificare, ordinea versiunilor, deduplicare, limite de apeluri și reluări controlate. Pentru loturi se verifică fiecare element. La timeout se verifică rezultatul înainte de repetarea operațiunilor cu efect financiar sau logistic.'],
 ['Acces și confidențialitate','Acces pe drepturi minime și separare între clienți, administratori și integratori; semnături la notificări; URL-uri temporare pentru documente. Parolele, tokenurile și datele complete ale cardului nu apar în răspunsuri sau jurnale.'],
 ['Sursa de inspirație','Fișierul Pasted text.txt furnizat de utilizator: liste API eMAG, Trendyol, Altex și Okazii. Funcțiile au fost generalizate și completate pentru fluxul propriu cesiro.com.'],
 ['Context public','https://cesiro.com/ — consultat la 22.10.2026 pentru contextul magazinului: catalog, cont, coș și limbi. Pagina publică nu confirmă existența sau schema unui API.'],
 ['Pas de implementare','Pentru fiecare funcție aprobată: se aleg sistemul responsabil, furnizorul, endpointul, metoda HTTP, drepturile, câmpurile obligatorii, exemplele cerere/răspuns și criteriile de acceptare.']
];
